import 'package:dartz/dartz.dart';import 'package:dio/dio.dart';import 'package:zan/Core/Storage/Remote/api_error_handler.dart';import 'package:zan/Features/Explore/data/entities/all_categories_entities.dart';import 'package:zan/Features/Explore/data/entities/category_data_entities.dart';import '../../data/repositories/explore_repo.dart';import '../../data/sources/explore_data.dart';class ExploreRepoImpl extends ExploreRepo {  @override  Future<Either<Failure, List<AllCategoriesEntities>>>      getAllCategories() async {    try {      final response = await ExploreData.getAllCategories();      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }  @override  Future<Either<Failure, List<CategoryDataPreviewEntities>>>      getCategoriesDetails({required int id}) async {    try {      final response = await ExploreData.getProductsCategory(id: id);      return right(response);    } catch (e) {      if (e is DioException) {        return left(ServerFailure.fromDioError(e));      } else {        return left(ServerFailure.fromResponse(e.hashCode, e));      }    }  }}